(function(){"use strict";
var $=function(id){return document.getElementById(id)},KEY="diario-fe-jardim-v1",data={letters:[],miracles:[]};
function valid(x){return x&&typeof x.id==="string"&&x.id.length<100&&typeof x.title==="string"&&x.title.length<=90&&typeof x.text==="string"&&x.text.length<=12000&&typeof x.created==="string"&&(!x.reopen||/^\d{4}-\d{2}-\d{2}$/.test(x.reopen))}
function clean(x){return{letters:Array.isArray(x&&x.letters)?x.letters.filter(valid).slice(0,500):[],miracles:Array.isArray(x&&x.miracles)?x.miracles.filter(valid).slice(0,500):[]}}
try{data=clean(JSON.parse(localStorage.getItem(KEY)||"{}"))}catch(e){}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch(e){alert("Não foi possível salvar. Confira o espaço do navegador.");return false}}
function today(){var d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function makeId(){return Date.now().toString(36)+Math.random().toString(36).slice(2,11)}
function elem(tag,content){var n=document.createElement(tag);if(content!==undefined)n.textContent=content;return n}
function renderList(type){var box=$(type),items=data[type].slice().reverse();box.textContent="";if(!items.length){box.appendChild(elem("p",type==="letters"?"Suas cartas aparecerão aqui. 💌":"Seu primeiro bilhetinho está esperando por você. 🫙"));return}
items.forEach(function(item){var locked=type==="letters"&&item.reopen&&item.reopen>today(),article=elem("article");article.className="entry";article.appendChild(elem("small",new Date(item.created).toLocaleDateString("pt-BR")));article.appendChild(elem("h3",locked?"💌 Carta guardada para o futuro":item.title));article.appendChild(elem("p",locked?"Você poderá reler esta carta em "+item.reopen.split("-").reverse().join("/")+".":item.text));var del=elem("button","Excluir");del.type="button";del.className="secondary";del.onclick=function(){if(!confirm("Deseja excluir este registro?"))return;var previous=data[type];data[type]=data[type].filter(function(x){return x.id!==item.id});if(save())render();else data[type]=previous};article.appendChild(del);box.appendChild(article)})}
function render(){renderList("letters");renderList("miracles");var total=data.letters.length+data.miracles.length;$("count-letters").textContent="💌 "+data.letters.length+" cartas";$("count-miracles").textContent="🫙 "+data.miracles.length+" gratidões";$("count-leaves").textContent="🌿 "+Math.min(36,total)+" folhas";$("tree").textContent=total===0?"🌱":total<4?"🌿":total<10?"🌳":"🌳🌸";$("tree").setAttribute("aria-label","Árvore da fé com "+Math.min(36,total)+" folhas simbólicas")}
$("letter-form").onsubmit=function(e){e.preventDefault();var title=$("letter-title").value.trim(),text=$("letter-text").value.trim(),reopen=$("letter-date").value;if(!title||!text)return;if(reopen&&reopen<=today()){alert("Escolha uma data futura ou deixe em branco.");return}var item={id:makeId(),title:title,text:text,reopen:reopen,created:new Date().toISOString()};data.letters.push(item);if(save()){this.reset();render();alert("Sua carta foi guardada. 💌")}else data.letters.pop()};
$("miracle-form").onsubmit=function(e){e.preventDefault();var title=$("miracle-title").value.trim(),text=$("miracle-text").value.trim();if(!title||!text)return;var item={id:makeId(),title:title,text:text,created:new Date().toISOString()};data.miracles.push(item);if(save()){this.reset();render()}else data.miracles.pop()};
$("random").onclick=function(){var m=$("memory");m.hidden=false;if(!data.miracles.length){m.textContent="Seu primeiro testemunho ainda vai florescer. 💗";return}var item=data.miracles[Math.floor(Math.random()*data.miracles.length)];m.textContent="✨ "+item.title+" — "+item.text};
$("export").onclick=function(){var blob=new Blob([JSON.stringify({kind:"jardim-v1",letters:data.letters,miracles:data.miracles},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="meu-jardim-"+today()+".json";document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},3000);$("status").textContent="Cópia preparada. Guarde o arquivo em local privado."};
$("import-button").onclick=function(){$("import-file").click()};
$("import-file").onchange=function(){var file=this.files&&this.files[0];if(!file)return;if(file.size>3000000){$("status").textContent="Arquivo muito grande.";return}var reader=new FileReader();reader.onload=function(){try{var raw=JSON.parse(reader.result);if(raw.kind!=="jardim-v1"||!Array.isArray(raw.letters)||!Array.isArray(raw.miracles))throw Error("Formato");var incoming=clean(raw),old=JSON.stringify(data),seen={};data.letters.concat(data.miracles).forEach(function(x){seen[x.id]=true});var added=0;["letters","miracles"].forEach(function(type){incoming[type].forEach(function(x){if(!seen[x.id]){data[type].push(x);seen[x.id]=true;added++}})});if(save()){render();$("status").textContent=added+" registros restaurados."}else data=JSON.parse(old)}catch(e){$("status").textContent="Não foi possível restaurar. Confira se é um backup do jardim."}};reader.onerror=function(){$("status").textContent="Não foi possível ler o arquivo."};reader.readAsText(file);this.value=""};
render();
})();